namespace Baseera.App.Services;

public static class I18n
{
    static I18n() { foreach (var pair in DeviceStrings.Words) Words.Add(pair.Key, pair.Value); }
    public static string T(string key)
    {
        int i = Settings.Current.Language switch { "ar" => 0, "fr" => 2, "es" => 3, _ => 1 };
        return Words.TryGetValue(key, out var values) ? values[i] : key;
    }
    public static readonly Dictionary<string, string[]> Words = new()
    {
        ["aiSettingsTitle"] = ["خدمة الذكاء الاصطناعي", "AI service", "Service d’IA", "Servicio de IA"],
        ["aiSettingsHelp"] = ["اختر الخدمة وطريقة الاتصال، وأضف المفتاح أو سجّل الدخول، ثم اختر النموذج واحفظ الإعدادات. تُستخدم هذه الإعدادات في المساعد وترجمة النوافذ.", "Choose a service and connection method, add a key or sign in, then select a model and save. The assistant and window translation use these settings.", "Choisissez le service et la connexion, ajoutez une clé ou connectez-vous, puis choisissez le modèle et enregistrez. Ces réglages servent à l’assistant et à la traduction.", "Elige servicio y conexión, añade una clave o inicia sesión, selecciona el modelo y guarda. El asistente y la traducción usan estos ajustes."],
        ["aiProbe"] = ["جرّب الاتصال", "Test connection", "Tester la connexion", "Probar conexión"],
        ["aiProbeHelp"] = ["الاختبار اختياري وقد يستهلك رصيدًا لدى الخدمة. يرسل طلبًا واحدًا مع صورة تجريبية صغيرة فقط، دون محادثاتك أو مرفقاتك أو بيانات التشخيص.", "Optional test; the service may charge for it. Sends one request with a tiny test image, without your conversations, attachments or diagnostics.", "Test facultatif, potentiellement facturé. Une requête avec une petite image de test, sans conversations, pièces jointes ni diagnostics.", "Prueba opcional; el servicio puede cobrarla. Envía una solicitud con una imagen pequeña de prueba, sin chats, adjuntos ni diagnósticos."],
        ["aiProbeNeedsSetup"] = ["أكمل إعداد الخدمة والنموذج أولًا.", "Complete the service and model setup first.", "Configurez d’abord le service et le modèle.", "Configura primero el servicio y el modelo."],
        ["aiProbeRunning"] = ["جارٍ اختبار الاتصال بالنموذج المختار…", "Testing the selected model…", "Test du modèle choisi…", "Probando el modelo seleccionado…"],
        ["aiProbePassed"] = ["نجح الاختبار خلال {0} ثانية، وطابق الرد صورة الاختبار.", "Test passed in {0}s; the answer matched the test image.", "Test réussi en {0}s ; la réponse correspond à l’image.", "Prueba superada en {0}s; la respuesta coincidió con la imagen."],
        ["aiProbePartial"] = ["استقبلنا ردًا خلال {0} ثانية، لكن لم نتأكد من مطابقة الصورة. راجع دعم النموذج للصور.", "Response received in {0}s, but the image answer was not confirmed. Review the model’s image support.", "Réponse reçue en {0}s, mais l’image n’a pas été confirmée. Vérifiez la prise en charge des images.", "Respuesta recibida en {0}s, pero no se confirmó la imagen. Revisa la compatibilidad visual del modelo."],
        ["aiProbeFailed"] = ["لم ينجح الاختبار. تحقق من الاتصال والمفتاح وتوفر النموذج وحدود استخدام حسابك، ثم أعد المحاولة.", "Test failed. Check connectivity, key, model availability and account usage limits, then retry.", "Échec du test. Vérifiez connexion, clé, disponibilité du modèle et limites du compte, puis réessayez.", "La prueba falló. Revisa conexión, clave, disponibilidad del modelo y límites de uso; vuelve a intentarlo."],
        ["aiProbeCancelled"] = ["أُلغي الاختبار. لم تُعدّل إعدادات الاتصال.", "Test canceled. Connection settings were not changed.", "Test annulé. Les réglages de connexion n’ont pas changé.", "Prueba cancelada. No se modificaron los ajustes de conexión."],
        ["aiProbeTimedOut"] = ["انتهت مهلة الاختبار. يمكنك إعادة المحاولة عند تحسن الاتصال.", "Test timed out. Retry when connectivity improves.", "Délai du test dépassé. Réessayez lorsque la connexion s’améliore.", "La prueba agotó el tiempo. Reintenta cuando mejore la conexión."],
        ["aiChatReady"] = ["الإعدادات محفوظة. يمكنك فتح مساعد الأخطاء وبدء المحادثة.", "Settings are saved. Open the error assistant to start chatting.", "Réglages enregistrés. Ouvrez l’assistant pour discuter.", "Ajustes guardados. Abre el asistente para conversar."],
        ["aiSaveBeforeChat"] = ["احفظ الإعدادات لتطبيق هذا الاتصال في المساعد.", "Save settings to use this connection in the assistant.", "Enregistrez les réglages pour utiliser cette connexion dans l’assistant.", "Guarda los ajustes para usar esta conexión en el asistente."],
        ["aiSettingsSaved"] = ["حُفظت إعدادات خدمة الذكاء الاصطناعي.", "AI service settings saved.", "Réglages du service d’IA enregistrés.", "Ajustes del servicio de IA guardados."],
        ["aiSavedAndTested"] = ["الإعدادات محفوظة، ونجح اختبار هذا الاتصال. يمكنك فتح المساعد.", "Settings saved and this connection tested successfully. You can open the assistant.", "Réglages enregistrés et connexion testée avec succès. Vous pouvez ouvrir l’assistant.", "Ajustes guardados y conexión probada. Puedes abrir el asistente."],
        ["aiSetupRequired"] = ["أكمل إعداد خدمة الذكاء الاصطناعي في إعدادات بصيرة، ثم عد إلى المحادثة.", "Set up the AI service in Baseera Settings, then return to this conversation.", "Configurez le service d’IA dans les paramètres Baseera, puis revenez à la conversation.", "Configura el servicio de IA en Ajustes de Baseera y vuelve a la conversación."],
        ["aiOpenSettings"] = ["فتح إعدادات الخدمة", "Open service settings", "Ouvrir les paramètres du service", "Abrir ajustes del servicio"],
        ["aiConnectionNotConfigured"] = ["لم تُضبط خدمة الذكاء الاصطناعي بعد.", "AI service is not configured yet.", "Le service d’IA n’est pas encore configuré.", "El servicio de IA aún no está configurado."],
        ["aiFinishBeforeSettings"] = ["أوقف الطلب أو التسجيل الجاري قبل الانتقال إلى الإعدادات. ستبقى محادثتك ومسودتك محفوظتين في النافذة.", "Stop the current request or recording before opening Settings. Your conversation and draft will stay in this window.", "Arrêtez la requête ou l’enregistrement avant les paramètres. La conversation et le brouillon resteront dans cette fenêtre.", "Detén la solicitud o grabación antes de abrir Ajustes. La conversación y el borrador seguirán en esta ventana."],
        ["assistantConversationIntro"] = ["اكتب رسالتك أو أرفق صورة أو فيديو، ثم تابع المحادثة. تُدار إعدادات خدمة الذكاء الاصطناعي من إعدادات بصيرة.", "Write a message or attach an image or video, then continue the conversation. Manage the AI connection in Baseera Settings.", "Écrivez ou joignez une image/vidéo, puis poursuivez. La connexion d’IA se gère dans les paramètres Baseera.", "Escribe o adjunta una imagen/vídeo y continúa. La conexión de IA se gestiona en Ajustes de Baseera."],
        ["chatConnectionChanged"] = ["تغيّرت الخدمة أو بيانات الاتصال خارج هذه النافذة. راجع الجهة والنموذج وطريقة إرسال المرفق ثم أرسل مجددًا عندما ترغب.", "The service/connection changed outside this window. Review the recipient, model and attachment mode, then Send again when ready.", "Le service/la connexion a changé ailleurs. Vérifiez le destinataire, le modèle et le mode des pièces jointes avant de renvoyer.", "El servicio/conexión cambió fuera de esta ventana. Revisa destinatario, modelo y modo del adjunto antes de enviar otra vez."],
        ["chatMore"] = ["المزيد", "More", "Plus", "Más"],
        ["chatEmptyTitle"] = ["كيف أساعدك في ويندوز؟", "What can I help you with?", "Comment puis-je vous aider ?", "¿En qué puedo ayudarte?"],
        ["chatEmptyHelp"] = ["اكتب الخطأ أو أرفق صورة أو فيديو قصيرًا. يمكنك متابعة الحديث، أو تسجيل شرحك ومراجعة نصه قبل الإرسال.", "Describe an error or attach an image or short video. Continue the conversation, or record your explanation and review its transcript before sending.", "Décrivez une erreur, joignez une image/vidéo courte ou enregistrez votre explication. Vérifiez le texte avant l’envoi.", "Describe el error, adjunta una imagen/vídeo corto o graba tu explicación. Revisa el texto antes de enviarlo."],
        ["chatContextPrivacy"] = ["يُرسل مع كل رسالة أحدث سياق نصي محدود للخدمة نفسها. لا يعاد رفع المرفقات أو سجلات التشخيص، وتُستبعد من السياق الإجابات التي استخدمت تلك السجلات. المحادثة مؤقتة؛ احفظها قبل الإغلاق إذا احتجتها.", "Each message includes bounded recent text for the same recipient. Attachments/logs are not reuploaded; replies using private logs are excluded from context. History is temporary; save it before closing if needed.", "Chaque message inclut un contexte textuel limité pour le même destinataire. Pièces jointes/journaux non renvoyés ; réponses liées aux journaux exclues. Historique temporaire : enregistrez-le si nécessaire.", "Cada mensaje incluye texto reciente limitado para el mismo destinatario. No se reenvían adjuntos/registros ni respuestas basadas en ellos. Historial temporal: guárdalo antes de cerrar si lo necesitas."],
        ["chatAttach"] = ["إرفاق", "Attach", "Joindre", "Adjuntar"],
        ["chatRecord"] = ["تسجيل صوت", "Record voice", "Enregistrer", "Grabar voz"],
        ["chatStopRecording"] = ["إيقاف التسجيل", "Stop recording", "Arrêter", "Detener grabación"],
        ["chatDictation"] = ["إملاء ويندوز", "Windows dictation", "Dictée Windows", "Dictado de Windows"],
        ["chatTools"] = ["الالتقاط والتشخيص", "Capture & diagnostics", "Capture et diagnostics", "Captura y diagnósticos"],
        ["chatNew"] = ["محادثة جديدة", "New chat", "Nouvelle conversation", "Nuevo chat"],
