        ["chatChooseVideo"] = ["اختيار فيديو", "Choose video", "Choisir une vidéo", "Elegir vídeo"],
        ["chatRemoveVideo"] = ["إزالة الفيديو", "Remove video", "Retirer la vidéo", "Quitar vídeo"],
        ["chatTranscribe"] = ["تحويل التسجيل إلى نص", "Transcribe recording", "Transcrire", "Transcribir grabación"],
