        ["chatPlaceholder"] = ["اكتب الخطأ أو تابع المحادثة… Enter للإرسال، Shift+Enter لسطر جديد.", "Describe the error or ask a follow-up… Enter sends, Shift+Enter adds a line.", "Décrivez l’erreur ou poursuivez… Entrée envoie, Maj+Entrée ajoute une ligne.", "Describe el error o continúa… Intro envía, Mayús+Intro añade una línea."],
        ["chatModels"] = ["تحميل النماذج", "Load models", "Charger les modèles", "Cargar modelos"],
        ["chatSend"] = ["إرسال", "Send", "Envoyer", "Enviar"],
        ["chatUsage"] = ["طلبات التحليل/النسخ المرسلة: {0} · السياق النصي: {1} تبادلًا حديثًا. لا يُعرف رصيد الخدمة الفعلي. {2}", "Analysis/transcription attempts: {0} · Context: {1} recent exchanges. Actual account balance is unknown. {2}", "Demandes d’analyse/transcription : {0} · Contexte : {1} échanges récents. Solde réel inconnu. {2}", "Intentos de análisis/transcripción: {0} · Contexto: {1} intercambios recientes. Saldo real desconocido. {2}"],
        ["chatOlderOmitted"] = ["تُعرض أحدث 20 إجابة فقط؛ يمكنك الاستمرار. الإجابات التي استخدمت سجلات خاصة لا يعاد إرسالها في السياق.", "Only the latest 20 answers are retained; you can continue. Replies based on private logs are not resent as context.", "Les 20 dernières réponses sont conservées ; vous pouvez continuer. Les réponses liées aux journaux privés ne sont pas renvoyées.", "Se conservan las últimas 20 respuestas; puedes continuar. No se reenvían respuestas basadas en registros privados."],
        ["chatUsageTitle"] = ["مراجعة الاستهلاك", "Usage checkpoint", "Point sur l’utilisation", "Revisar consumo"],
        ["chatCheckpointHelp"] = ["وصلت إلى 10 طلبات إضافية للتحليل أو النسخ الصوتي. هل تريد السماح بالعشرة التالية؟ لا تُرسل أي رسالة تلقائيًا. قد تُحتسب الطلبات الفاشلة، وقد ينفد رصيدك قبل هذا العدد؛ راجع استخدام الخدمة.", "You reached another 10 analysis/transcription attempts. Allow the next 10? No message is sent automatically. Failed requests may be billed, and your balance may run out sooner; check the service’s usage page.", "Vous avez atteint 10 demandes supplémentaires. Autoriser les 10 suivantes ? Aucun envoi automatique. Les échecs peuvent être facturés et le solde épuisé plus tôt ; consultez le service.", "Alcanzaste otros 10 intentos de análisis/transcripción. ¿Permitir los siguientes 10? No se envía nada automáticamente. Los fallos pueden cobrar y el saldo agotarse antes; revisa el servicio."],
        ["chatContinue"] = ["السماح بالمتابعة", "Allow continuation", "Autoriser la suite", "Permitir continuar"],
        ["chatPause"] = ["التوقف هنا", "Stop here", "S’arrêter ici", "Parar aquí"],
        ["chatPaused"] = ["توقفت الطلبات. يمكنك السماح بالمتابعة عندما ترغب.", "Requests paused. Allow continuation when you are ready.", "Demandes suspendues. Reprenez quand vous le souhaitez.", "Solicitudes en pausa. Permite continuar cuando quieras."],
        ["chatSelectModel"] = ["اختر نموذجًا متاحًا من القائمة.", "Choose an available model from the list.", "Choisissez un modèle disponible.", "Elige un modelo disponible."],
        ["chatModelChanged"] = ["سيُستخدم النموذج المختار مع الرسالة التالية.", "Selected model applies to the next message.", "Le modèle choisi sera utilisé au prochain message.", "El modelo elegido se usará en el próximo mensaje."],
        ["chatRecipientChange"] = ["تغيّرت الخدمة أو الحساب. لحماية الخصوصية، لن ننقل نص المحادثة السابقة. هل تبدأ محادثة جديدة مع الجهة المختارة؟ احفظ المحادثة الحالية أولًا إذا احتجتها.", "The service/account changed. Previous conversation text will not be transferred. Start a new conversation for this recipient? Save the current conversation first if needed.", "Le service/compte a changé. Aucun ancien échange ne sera transféré. Commencer une nouvelle conversation ? Enregistrez l’actuelle si nécessaire.", "El servicio/cuenta cambió. No se transferirá el chat anterior. ¿Empezar uno nuevo? Guarda el actual primero si lo necesitas."],
        ["chatClearConfirm"] = ["تبدأ محادثة جديدة ويُمسح السجل المؤقت من النافذة. احفظه أولًا إذا احتجته. هل تتابع؟", "Start a new chat and clear this window’s temporary history? Save it first if needed.", "Commencer un nouvel échange et effacer l’historique temporaire ? Enregistrez-le si nécessaire.", "¿Iniciar un chat nuevo y borrar el historial temporal? Guárdalo primero si lo necesitas."],
        ["chatVideoNative"] = ["سيُرسل الفيديو الأصلي، بما فيه الصوت والبيانات الوصفية، إلى Gemini مع الإرسال.", "Sending will upload the original video, including audio and metadata, to Gemini.", "L’envoi transmet la vidéo originale, son et métadonnées compris, à Gemini.", "Al enviar se subirá el vídeo original, con audio y metadatos, a Gemini."],
        ["chatVideoFrames"] = ["ستُرسل 6 لقطات موزعة فقط، دون الفيديو الأصلي أو الصوت. قد تفوتها تفاصيل بين اللقطات.", "Only 6 sampled frames will be sent, without the original video or audio. Events between samples can be missed.", "Seules 6 images seront envoyées, sans vidéo originale ni son. Des détails peuvent être manqués.", "Se enviarán solo 6 fotogramas, sin vídeo original ni audio. Se pueden perder detalles entre muestras."],
        ["chatVideoUnsupported"] = ["تعذر فك الفيديو أو لا تدعمه ترميزات ويندوز المثبتة. جرّب MP4 قصيرًا أو صورة من الخطأ.", "Video decoding failed or Windows codecs do not support it. Try a short MP4 or an error screenshot.", "Décodage impossible ou codec Windows absent. Essayez un court MP4 ou une capture.", "No se pudo decodificar el vídeo o falta el códec de Windows. Prueba un MP4 corto o captura."],
        ["chatVideoLimit"] = ["الفيديو يجب ألا يتجاوز 12 ميغابايت و60 ثانية، وبأبعاد مدعومة.", "Video must be at most 12 MB and 60 seconds with supported dimensions.", "Vidéo : 12 Mo et 60 secondes au maximum, dimensions compatibles.", "Vídeo: máximo 12 MB y 60 segundos con dimensiones compatibles."],
        ["chatVideoSamples"] = ["ست لقطات من الفيديو", "Six video samples", "Six images de la vidéo", "Seis muestras del vídeo"],
        ["chatVideoPreparing"] = ["تحضير معاينة الفيديو محليًا…", "Preparing video locally…", "Préparation locale de la vidéo…", "Preparando vídeo localmente…"],
        ["chatVideoReady"] = ["الفيديو جاهز؛ راجع طريقة الإرسال قبل إرساله.", "Video ready; review how it will be sent.", "Vidéo prête ; vérifiez le mode d’envoi.", "Vídeo listo; revisa cómo se enviará."],
        ["chatRecording"] = ["يجري التسجيل محليًا: {0} ثانية، بحد 120 ثانية. لا يجري رفع الصوت.", "Recording locally: {0}s, up to 120s. Audio is not being uploaded.", "Enregistrement local : {0}s, maximum 120s. Aucun envoi audio.", "Grabando localmente: {0}s, máximo 120s. No se está subiendo audio."],
        ["chatRecordingReady"] = ["تسجيل محلي جاهز: {0} ثانية.", "Local recording ready: {0}s.", "Enregistrement local prêt : {0}s.", "Grabación local lista: {0}s."],
        ["chatAudioPrivacy"] = ["تحويل التسجيل يرفع الصوت إلى الخدمة المختارة وقد يستهلك رصيدًا. راجع النص الناتج وعدّله؛ لن يُرسل إلى المحادثة قبل ضغط إرسال.", "Transcription uploads audio to the selected service and may incur charges. Review/edit the result; it is not sent to the chat until you press Send.", "La transcription envoie l’audio au service et peut être facturée. Relisez le texte ; il n’est envoyé au chat qu’avec Envoyer.", "Transcribir sube el audio al servicio y puede cobrar. Revisa el texto; no se envía al chat hasta pulsar Enviar."],
        ["chatAudioUnsupported"] = ["النسخ الصوتي المباشر متاح مع مفتاح Gemini أو OpenAI أو Groq، وليس تسجيل دخول ChatGPT. يمكنك استخدام إملاء ويندوز مع أي خدمة.", "Direct transcription needs a Gemini, OpenAI or Groq API key, not ChatGPT sign-in. Windows dictation works independently of your AI service.", "La transcription directe nécessite une clé Gemini, OpenAI ou Groq, pas la connexion ChatGPT. La dictée Windows est indépendante du service.", "La transcripción directa requiere clave Gemini, OpenAI o Groq, no inicio ChatGPT. El dictado de Windows es independiente del servicio."],
        ["chatMicFailed"] = ["تعذر فتح الميكروفون. تحقق من الجهاز وأذونات الميكروفون في ويندوز.", "Could not open the microphone. Check the device and Windows microphone permissions.", "Microphone indisponible. Vérifiez l’appareil et les autorisations Windows.", "No se pudo abrir el micrófono. Revisa el dispositivo y permisos de Windows."],
        ["chatAudioEmpty"] = ["لم تتوفر بيانات صوت صالحة في التسجيل.", "No valid audio data was recorded.", "Aucune donnée audio valide enregistrée.", "No se grabó audio válido."],
        ["chatReviewAudio"] = ["حوّل التسجيل إلى نص وراجعه، أو احذفه، قبل إرسال الرسالة.", "Transcribe and review the recording, or discard it, before sending.", "Transcrivez et vérifiez l’audio, ou supprimez-le, avant l’envoi.", "Transcribe y revisa la grabación, o descártala, antes de enviar."],
        ["chatTranscribing"] = ["تحويل التسجيل إلى نص…", "Transcribing recording…", "Transcription en cours…", "Transcribiendo grabación…"],
        ["chatTranscriptReady"] = ["النص جاهز للمراجعة والتعديل. اضغط إرسال عندما ترغب.", "Transcript ready to review/edit. Press Send when ready.", "Texte prêt à vérifier/modifier. Envoyez quand vous le souhaitez.", "Texto listo para revisar/editar. Pulsa Enviar cuando quieras."],
        ["chatAudioFailed"] = ["تعذر تحويل التسجيل إلى نص.", "Could not transcribe the recording.", "Transcription impossible.", "No se pudo transcribir la grabación."],
        ["chatDictationHelp"] = ["إملاء ويندوز يستخدم إعدادات الكلام والخصوصية الخاصة بمايكروسوفت وقد يحتاج الإنترنت. راجع النص ثم اضغط إرسال.", "Windows dictation uses Microsoft speech/privacy settings and may need internet. Review the text, then Send.", "La dictée Windows utilise les paramètres vocaux/confidentialité Microsoft et peut nécessiter Internet. Vérifiez puis envoyez.", "El dictado de Windows usa ajustes de voz/privacidad de Microsoft y puede necesitar internet. Revisa el texto y envíalo."],
        ["chatNothingToExport"] = ["لا توجد رسائل مكتملة للحفظ بعد.", "No completed messages to save yet.", "Aucun message terminé à enregistrer.", "Aún no hay mensajes completos para guardar."],
