        ["adviceCode"] = ["نص للمراجعة", "Text to review", "Texte à vérifier", "Texto para revisar"],
        ["adviceResponseTime"] = ["وصل الرد خلال {0} ث", "Response received in {0}s", "Réponse reçue en {0}s", "Respuesta recibida en {0}s"],
        ["smartMatchHelp"] = ["تصفية اختيارية باسم التطبيق أو رمز الخطأ (نص حرفي). يبحث في أحدث 200 حدث ضمن الفترة؛ قد تُحذف أحداث أقدم أو غير مطابقة.", "Optional app name or error code filter (literal text). Searches the latest 200 events in the range; older or nonmatching events may be omitted.", "Filtre facultatif par application ou code d’erreur (texte littéral). Recherche dans les 200 événements récents ; les autres peuvent être omis.", "Filtro opcional por aplicación o código de error (texto literal). Busca en los últimos 200 eventos; se pueden omitir otros eventos."],
        ["smartTimeRange"] = ["فترة أحداث ويندوز", "Windows event time range", "Période des événements Windows", "Periodo de eventos de Windows"],
        ["smartHours"] = ["آخر {0} ساعة", "Last {0} hours", "Dernières {0} heures", "Últimas {0} horas"],
        ["smartEvidenceTitle"] = ["ملخص الأدلة المحلي", "Local evidence overview", "Aperçu local des éléments", "Resumen local de evidencias"],
        ["smartEvidenceCounts"] = ["الأحداث المعروضة: {0} · رموز الخطأ: {1} · تنبيهات التغطية: {2}", "Events in preview: {0} · Error codes: {1} · Coverage notices: {2}", "Événements dans l’aperçu : {0} · Codes d’erreur : {1} · Avis : {2}", "Eventos en vista previa: {0} · Códigos de error: {1} · Avisos: {2}"],
        ["smartObservationSaved"] = ["حُفظت ملاحظتك في سجل الحالة المؤقت.", "Observation recorded in this case.", "Observation ajoutée au suivi du problème.", "Observación registrada en este caso."],
        ["smartEvidenceLimits"] = ["ملخص آلي للنص المعروض فقط. التكرار أو توقيت الحدث لا يثبت سبب المشكلة. راجع تنبيهات المصادر والبيانات الناقصة أدناه.", "Local index of the displayed text only. Repetition or timing does not establish the cause. Review source and missing-data notices below.", "Index local du texte affiché uniquement. La répétition ou la proximité temporelle ne prouve pas la cause. Consultez les avis ci-dessous.", "Índice local del texto mostrado. La repetición o cercanía temporal no demuestra la causa. Revisa los avisos de fuentes y datos omitidos."],
        ["smartSessionTitle"] = ["متابعة الحالة", "Case follow-up", "Suivi du problème", "Seguimiento del caso"],
        ["smartSessionHelp"] = ["أعد تجربة العملية التي كانت تفشل، ثم سجّل ما لاحظته. النتيجة من ملاحظتك وليست فحصًا آليًا. يبقى سجل هذه الحالة في الذاكرة حتى تحليل جديد أو إغلاق النافذة.", "Retry the operation that failed, then record what you observed. Your report is not automatic verification. This case stays in memory until a new analysis or closing this window.", "Réessayez l’opération, puis indiquez votre observation. Ce n’est pas une vérification automatique. Le cas reste en mémoire jusqu’à une nouvelle analyse ou la fermeture.", "Repite la operación y registra lo observado. Tu informe no es una verificación automática. El caso permanece en memoria hasta otro análisis o cerrar la ventana."],
        ["smartResolved"] = ["اختفت المشكلة عند التجربة", "Problem no longer occurs", "Le problème ne se reproduit plus", "El problema ya no ocurre"],
        ["smartUnresolved"] = ["ما زالت المشكلة موجودة", "Problem still occurs", "Le problème persiste", "El problema persiste"],
        ["smartUserResolved"] = ["سجّلتَ اختفاء المشكلة عند التجربة؛ لم يتحقق التطبيق منها بصورة مستقلة.", "You reported that the problem no longer occurs; the app has not independently verified this.", "Vous avez signalé la disparition du problème ; l’application ne l’a pas vérifiée indépendamment.", "Indicaste que el problema ya no ocurre; la aplicación no lo ha verificado de forma independiente."],
        ["smartUserUnresolved"] = ["سجّلتَ استمرار المشكلة. أضف ما حدث إلى الوصف، واجمع بيانات حديثة عند الحاجة، ثم راجعها ووافق على مشاركتها قبل التحليل مجددًا.", "You reported that the problem persists. Add what happened to the description, collect fresh diagnostics if useful, then review and approve sharing before analyzing again.", "Vous avez signalé que le problème persiste. Complétez la description, recueillez si utile de nouvelles données, puis vérifiez et autorisez leur partage avant une nouvelle analyse.", "Indicaste que el problema persiste. Completa la descripción, recopila datos nuevos si son útiles y revisa y autoriza su envío antes de analizar otra vez."],
        ["smartReportInclude"] = ["تضمين بيانات التشخيص التي أرسلتها في هذا التحليل (اختياري)", "Include diagnostics sent in this analysis (optional)", "Inclure les diagnostics envoyés pour cette analyse (facultatif)", "Incluir diagnósticos enviados en este análisis (opcional)"],
        ["smartSaveReport"] = ["حفظ تقرير الحالة", "Save case report", "Enregistrer le rapport", "Guardar informe del caso"],
        ["smartReportPrivacy"] = ["الحفظ محلي فقط: الوصف والإرشادات وسجل الإصلاح وملاحظاتك. لا تُرفق الصورة أو مفاتيح الاتصال. التشخيصات مستبعدة افتراضيًا. التنقيح تقريبي؛ راجع ملف JSON قبل مشاركته.", "Local save only: description, advice, repair activity and your observations. No image or connection keys. Diagnostics are excluded by default. Redaction is best effort; review the JSON before sharing.", "Enregistrement local : description, conseils, actions et observations. Sans image ni clé. Diagnostics exclus par défaut. Masquage imparfait : relisez le JSON avant partage.", "Guardado local: descripción, consejos, actividad y observaciones. Sin imagen ni claves. Diagnósticos excluidos por defecto. La ocultación es imperfecta: revisa el JSON antes de compartirlo."],
        ["smartReportSaved"] = ["حُفظ تقرير الحالة على جهازك.", "Case report saved on your device.", "Rapport enregistré sur votre appareil.", "Informe guardado en tu dispositivo."],
        ["aiConnectionMethod"] = ["طريقة الاتصال", "Connection method", "Mode de connexion", "Método de conexión"],
        ["aiApiConnection"] = ["مفتاح API", "API key", "Clé API", "Clave API"],
        ["chatGptConnection"] = ["حساب ChatGPT", "ChatGPT account", "Compte ChatGPT", "Cuenta de ChatGPT"],
        ["chatGptAccount"] = ["حساب ChatGPT", "ChatGPT account", "Compte ChatGPT", "Cuenta de ChatGPT"],
        ["chatGptContinue"] = ["المتابعة باستخدام ChatGPT", "Continue with ChatGPT", "Continuer avec ChatGPT", "Continuar con ChatGPT"],
        ["chatGptEligibility"] = ["استخدم خطة ChatGPT المؤهلة أو رصيدها دون إدخال مفتاح API. تُطلب موافقتك في صفحة OpenAI الرسمية، وتطبق حدود الحساب والخطة.", "Use an eligible ChatGPT plan or its credits without entering an API key. Consent happens on the official OpenAI page; account and plan limits apply.", "Utilisez un forfait ChatGPT éligible ou ses crédits sans clé API. Le consentement se fait sur la page officielle OpenAI ; les limites du compte et du forfait s’appliquent.", "Usa un plan de ChatGPT apto o sus créditos sin clave API. La autorización se realiza en la página oficial de OpenAI; se aplican los límites de la cuenta y del plan."],
        ["chatGptAddAccount"] = ["إضافة حساب آخر", "Add another account", "Ajouter un compte", "Añadir otra cuenta"],
        ["chatGptSignOut"] = ["تسجيل الخروج", "Sign out", "Se déconnecter", "Cerrar sesión"],
        ["chatGptChooseAccount"] = ["سجّل الدخول أو اختر حسابًا محفوظًا ثم حمّل نماذجه.", "Sign in or choose a saved account, then load its models.", "Connectez-vous ou choisissez un compte enregistré, puis chargez ses modèles.", "Inicia sesión o elige una cuenta guardada y carga sus modelos."],
        ["chatGptManageUsage"] = ["إدارة استخدام ChatGPT", "Manage ChatGPT usage", "Gérer l’utilisation ChatGPT", "Gestionar uso de ChatGPT"],
        ["chatGptUsingPlan"] = ["تُستخدم خطة ChatGPT لهذا الاتصال.", "Using ChatGPT plan for this connection.", "Utilisation du forfait ChatGPT pour cette connexion.", "Se usa el plan de ChatGPT en esta conexión."],
        ["chatGptPlan"] = ["ضمن خطة ChatGPT", "ChatGPT plan", "Forfait ChatGPT", "Plan de ChatGPT"],
        ["chatGptWaiting"] = ["أكمل تسجيل الدخول والموافقة في المتصفح. يمكنك إلغاء المحاولة هنا.", "Complete sign-in and consent in your browser. You can cancel here.", "Terminez la connexion et le consentement dans le navigateur. Vous pouvez annuler ici.", "Completa el inicio de sesión y la autorización en tu navegador. Puedes cancelar aquí."],
        ["chatGptSignInCancelled"] = ["أُلغي تسجيل الدخول أو انتهت مهلته. يمكنك المحاولة مجددًا.", "Sign-in was cancelled or timed out. You can try again.", "Connexion annulée ou délai expiré. Vous pouvez réessayer.", "Se canceló el inicio de sesión o se agotó el tiempo. Puedes intentarlo de nuevo."],
        ["chatGptSignInFailed"] = ["لم يكتمل تسجيل الدخول بـChatGPT. حاول مجددًا وتحقق من الاتصال وأهلية الحساب.", "ChatGPT sign-in did not complete. Try again and check your connection and account eligibility.", "La connexion ChatGPT n’a pas abouti. Réessayez et vérifiez la connexion et l’éligibilité du compte.", "No se completó el inicio de sesión con ChatGPT. Reintenta y comprueba la conexión y si tu cuenta es apta."],
        ["chatGptStorageError"] = ["تعذّر قراءة جلسات ChatGPT المحمية أو حفظها. تحقق من صلاحيات مجلد بيانات بصيرة وحساب ويندوز.", "Could not read or save protected ChatGPT sessions. Check the Baseera data-folder permissions and Windows account.", "Impossible de lire ou d’enregistrer les sessions ChatGPT protégées. Vérifiez les droits du dossier de données et le compte Windows.", "No se pudieron leer o guardar las sesiones protegidas. Comprueba los permisos de la carpeta de datos y la cuenta de Windows."],
        ["chatGptInvalidResponse"] = ["لم تجتز استجابة تسجيل الدخول التحقق. أعد المحاولة من بصيرة.", "The sign-in response failed validation. Start again from Baseera.", "La réponse de connexion n’a pas passé la validation. Recommencez depuis Baseera.", "La respuesta de inicio de sesión no superó la validación. Empieza de nuevo desde Baseera."],
        ["chatGptIdentityMismatch"] = ["الحساب العائد لا يطابق الحساب المحدد. اختر إضافة حساب آخر للاتصال به.", "The returned account does not match the selected account. Use Add another account to connect it.", "Le compte reçu ne correspond pas au compte choisi. Utilisez Ajouter un compte.", "La cuenta recibida no coincide con la seleccionada. Usa Añadir otra cuenta."],
        ["chatGptDeclined"] = ["لم تُمنح موافقة تسجيل الدخول. يمكنك المحاولة مجددًا أو استخدام مفتاح API.", "Sign-in consent was not granted. Try again or use an API key.", "Le consentement n’a pas été accordé. Réessayez ou utilisez une clé API.", "No se concedió la autorización. Reintenta o usa una clave API."],
        ["chatGptConsentNeeded"] = ["لم يُمنح هذا الحساب إذن استخدام خطة ChatGPT. أعد تسجيل الدخول ووافق على الإذن المطلوب إذا كان حسابك مؤهلًا.", "This account has not granted ChatGPT plan usage. Sign in again and grant the requested permission if your account is eligible.", "Ce compte n’a pas autorisé l’utilisation du forfait ChatGPT. Reconnectez-vous et accordez l’autorisation si le compte est éligible.", "Esta cuenta no autorizó el uso del plan de ChatGPT. Vuelve a iniciar sesión y concede el permiso si tu cuenta es apta."],
        ["chatGptReconnect"] = ["انتهت جلسة ChatGPT أو رُفضت. سجّل الدخول مجددًا؛ لن يُستخدم مفتاح API بدلًا منها تلقائيًا.", "The ChatGPT session expired or was rejected. Sign in again; the app will not silently switch to an API key.", "La session ChatGPT a expiré ou a été refusée. Reconnectez-vous ; aucune bascule automatique vers une clé API.", "La sesión de ChatGPT caducó o fue rechazada. Vuelve a iniciar sesión; no se cambiará automáticamente a una clave API."],
        ["chatGptReturn"] = ["استلمت بصيرة استجابة تسجيل الدخول. عد إلى التطبيق لإكمال الاتصال؛ يمكنك إغلاق هذه الصفحة.", "Baseera received the sign-in response. Return to the app to finish connecting; you can close this page.", "Baseera a reçu la réponse de connexion. Revenez dans l’application ; vous pouvez fermer cette page.", "Baseera recibió la respuesta de inicio de sesión. Vuelve a la aplicación para terminar; puedes cerrar esta página."],
        ["chatGptInvalidCallback"] = ["لم تُقبل هذه الاستجابة. أكمل المحاولة التي بدأت من بصيرة.", "This response was not accepted. Complete the attempt started in Baseera.", "Cette réponse n’a pas été acceptée. Terminez la tentative commencée dans Baseera.", "No se aceptó esta respuesta. Completa el intento iniciado desde Baseera."],
        ["chatGptSignedOut"] = ["تم تسجيل الخروج وإزالة الحساب وبياناته المحفوظة من بصيرة.", "Signed out and removed this account and its saved profile from Baseera.", "Déconnexion effectuée : ce compte et son profil enregistré ont été supprimés de Baseera.", "Sesión cerrada; se eliminaron esta cuenta y su perfil guardado de Baseera."],
        ["chatGptRemovedTitle"] = ["تمت إزالة الحساب من بصيرة", "Account removed from Baseera", "Compte supprimé de Baseera", "Cuenta eliminada de Baseera"],
        ["chatGptCloseAssistantHelp"] = ["أغلق نافذة مساعد أخطاء ويندوز. عند فتحها مجددًا لن يظهر الحساب الذي سجّلت الخروج منه. مفاتيح API وإعداداتها محفوظة، وسيبقى تطبيق بصيرة مفتوحًا.", "Close the Windows error assistant. When you open it again, the signed-out account will no longer appear. API keys and their settings are preserved, and Baseera will stay open.", "Fermez l’assistant d’erreurs Windows. À sa réouverture, le compte déconnecté n’apparaîtra plus. Les clés API et leurs paramètres sont conservés ; Baseera reste ouvert.", "Cierra el asistente de errores de Windows. Al abrirlo de nuevo, la cuenta desconectada ya no aparecerá. Las claves API y sus ajustes se conservan; Baseera seguirá abierto."],
        ["chatGptCloseAssistant"] = ["إغلاق مساعد الأخطاء", "Close error assistant", "Fermer l’assistant", "Cerrar asistente"],
        ["chatGptCloseLater"] = ["الإغلاق لاحقًا", "Close later", "Fermer plus tard", "Cerrar más tarde"],
        ["chatGptRevocationUnconfirmed"] = ["حُذفت الجلسة محليًا، لكن تعذّر تأكيد إلغائها لدى OpenAI. افتح إدارة الاستخدام وافصل بصيرة من إعدادات ChatGPT.", "The local session was cleared, but OpenAI revocation could not be confirmed. Open Manage usage and disconnect Baseera in ChatGPT settings.", "La session locale a été supprimée, mais la révocation OpenAI n’a pas été confirmée. Déconnectez Baseera dans les paramètres ChatGPT.", "Se borró la sesión local, pero no se confirmó su revocación en OpenAI. Desconecta Baseera en la configuración de ChatGPT."],
        ["chatGptModelsFailed"] = ["تعذّر تحميل نماذج حساب ChatGPT.", "Could not load this ChatGPT account’s models.", "Impossible de charger les modèles de ce compte ChatGPT.", "No se pudieron cargar los modelos de esta cuenta de ChatGPT."],
        ["chatGptStreamFailed"] = ["لم يكتمل رد ChatGPT. أعد المحاولة؛ لا يُعرض الرد الجزئي كنتيجة مكتملة.", "The ChatGPT response did not complete. Try again; a partial reply is not treated as a completed result.", "La réponse ChatGPT n’est pas terminée. Réessayez ; une réponse partielle n’est pas un résultat complet.", "La respuesta de ChatGPT no se completó. Reintenta; una respuesta parcial no se trata como resultado completo."],
        ["chatGptUsageLimit"] = ["وصلت إلى حد استخدام خطة ChatGPT أو أن استخدامها غير متاح لهذا التطبيق. افتح إدارة الاستخدام لمراجعة حدود الحساب والتطبيق.", "Your ChatGPT plan usage limit was reached, or plan usage is unavailable for this app. Open Manage usage to review account and app limits.", "La limite du forfait ChatGPT a été atteinte ou son utilisation est indisponible. Ouvrez la gestion de l’utilisation pour vérifier les limites.", "Se alcanzó el límite del plan de ChatGPT o su uso no está disponible. Abre la gestión de uso para revisar los límites."],
        ["chatGptUsageOpenFailed"] = ["تعذّر فتح المتصفح. افتح chatgpt.com/settings/usage لإدارة الاستخدام.", "Could not open the browser. Visit chatgpt.com/settings/usage to manage usage.", "Impossible d’ouvrir le navigateur. Ouvrez chatgpt.com/settings/usage.", "No se pudo abrir el navegador. Visita chatgpt.com/settings/usage."],
        ["chatGptWelcomeTitle"] = ["أنت تستخدم خطة ChatGPT", "You’re using your ChatGPT plan", "Vous utilisez votre forfait ChatGPT", "Estás usando tu plan de ChatGPT"],
        ["chatGptWelcomeBody"] = ["طلبات الذكاء الاصطناعي المؤهلة في بصيرة تستخدم خطة ChatGPT أو رصيدها وفق حدود حسابك. يمكنك مراجعة الاستخدام والتحكم بوصول بصيرة من إعدادات ChatGPT. لا تُمنح بصيرة صلاحية قراءة محادثاتك.", "Eligible AI requests in Baseera use your ChatGPT plan or credits under your account limits. Review usage and manage Baseera’s access in ChatGPT settings. This does not grant access to your ChatGPT conversations.", "Les requêtes éligibles de Baseera utilisent votre forfait ChatGPT ou vos crédits selon vos limites. Gérez l’utilisation et l’accès de Baseera dans les paramètres ChatGPT. Aucun accès à vos conversations n’est accordé.", "Las solicitudes aptas de Baseera usan tu plan de ChatGPT o créditos según tus límites. Gestiona el uso y el acceso de Baseera en ChatGPT. Esto no da acceso a tus conversaciones."],
        ["chatGptGotIt"] = ["فهمت", "Got it", "Compris", "Entendido"],
        ["errorAssistantTitle"] = ["بصيرة Smart Repair", "Baseera Smart Repair", "Baseera Smart Repair", "Baseera Smart Repair"],
        ["errorAssistantIntro"] = ["الصق رسالة الخطأ أو صورته، أو التقط نافذة ظاهرة. ستحصل على تفسير وخطوات مقترحة يمكنك مراجعتها.", "Paste an error message or screenshot, or capture a visible window. Get an explanation and steps you can review.", "Collez le message ou une capture, ou capturez une fenêtre visible. Examinez l’explication et les étapes proposées.", "Pega el mensaje o una captura, o captura una ventana visible. Revisa la explicación y los pasos sugeridos."],
        ["errorShortcut"] = ["يمكنك فتح المساعد لاحقًا من بصيرة باختصار Ctrl+Shift+E.", "Open the assistant again from Baseera with Ctrl+Shift+E.", "Rouvrez l’assistant depuis Baseera avec Ctrl+Shift+E.", "Vuelve a abrir el asistente desde Baseera con Ctrl+Shift+E."],
        ["errorConnect"] = ["إعداد خدمة الذكاء الاصطناعي", "Set up AI service", "Configurer le service IA", "Configurar el servicio de IA"],
        ["errorConnectHelp"] = ["اختر الخدمة، ثم أضف مفتاح API أو سجّل الدخول بالحساب المدعوم، وحمّل نماذج الصور. يُستخدم الاتصال نفسه لترجمة النوافذ.", "Choose a service, then add its API key or sign in with a supported account and load image-capable models. Window translation shares this connection.", "Choisissez le service, ajoutez sa clé ou connectez un compte compatible, puis chargez les modèles avec vision. La traduction utilise cette connexion.", "Elige el servicio, añade su clave o conecta una cuenta compatible y carga sus modelos con visión. La traducción comparte esta conexión."],
        ["errorKeyLocal"] = ["يُحفظ المفتاح محميًا بحساب ويندوز. يمكنك إغلاق النافذة ومتابعة استخدام بقية التطبيق من دونه.", "The key is protected with your Windows account. You can close this window and use the rest of the app without it.", "La clé est protégée par votre compte Windows. Vous pouvez fermer cette fenêtre et utiliser le reste de l’application sans clé.", "La clave se protege con tu cuenta de Windows. Puedes cerrar esta ventana y usar el resto de la aplicación sin ella."],
        ["errorSaveKey"] = ["حفظ والمتابعة", "Save and continue", "Enregistrer et continuer", "Guardar y continuar"],
        ["errorConfigure"] = ["تغيير خدمة الذكاء الاصطناعي", "Change AI service", "Changer de service IA", "Cambiar servicio de IA"],
        ["errorKeyMissing"] = ["أضف مفتاح الخدمة وحمّل النماذج واختر نموذجًا.", "Add a service key, load models, and choose one.", "Ajoutez une clé, chargez les modèles et choisissez-en un.", "Añade una clave, carga los modelos y elige uno."],
        ["errorKeySaved"] = ["حُفظ إعداد الخدمة.", "Service settings saved.", "Réglages du service enregistrés.", "Configuración del servicio guardada."],
        ["errorSaveFailed"] = ["تعذّر حفظ الإعداد:", "Could not save settings:", "Impossible d’enregistrer les réglages :", "No se pudieron guardar los ajustes:"],
        ["errorDescription"] = ["رسالة الخطأ أو ما حدث", "Error message or what happened", "Message d’erreur ou description", "Mensaje de error o qué ocurrió"],
        ["errorDescriptionHint"] = ["الصق النص هنا أو اكتب وصفًا قصيرًا…", "Paste the message or describe the problem…", "Collez le message ou décrivez le problème…", "Pega el mensaje o describe el problema…"],
        ["errorPaste"] = ["لصق من الحافظة", "Paste from clipboard", "Coller depuis le presse-papiers", "Pegar del portapapeles"],
        ["errorChooseImage"] = ["اختيار صورة", "Choose image", "Choisir une image", "Elegir imagen"],
        ["errorRemoveImage"] = ["إزالة الصورة", "Remove image", "Supprimer l’image", "Quitar imagen"],
        ["errorNoImage"] = ["لم تُضف صورة بعد", "No image added", "Aucune image ajoutée", "No se ha añadido ninguna imagen"],
        ["errorClipboardImage"] = ["صورة من الحافظة", "Clipboard image", "Image du presse-papiers", "Imagen del portapapeles"],
        ["errorPasted"] = ["أُضيف محتوى الحافظة.", "Clipboard content added.", "Contenu du presse-papiers ajouté.", "Contenido del portapapeles añadido."],
        ["errorEmptyClipboard"] = ["لا يوجد نص أو صورة في الحافظة.", "No text or image on the clipboard.", "Aucun texte ni image dans le presse-papiers.", "No hay texto ni imagen en el portapapeles."],
        ["errorClipboardFailed"] = ["تعذّر الوصول إلى الحافظة:", "Could not access clipboard:", "Accès au presse-papiers impossible :", "No se pudo acceder al portapapeles:"],
        ["errorCaptureWindow"] = ["أو التقط نافذة مفتوحة", "Or capture an open window", "Ou capturer une fenêtre ouverte", "O captura una ventana abierta"],
