        ["selfCheckFailed"] = ["تعذّر البحث عن تحديث. تحقق من الاتصال وحاول مجددًا.", "Could not check for updates. Check your connection and try again.", "Recherche impossible. Vérifiez votre connexion et réessayez.", "No se pudo buscar. Revisa tu conexión y reintenta."],
