        ["disabled"] = ["متوقف", "Disabled", "Désactivé", "Desactivado"],
        ["disabledDesc"] = ["هذه الأداة متوقفة. فعّلها من الإعدادات لاستخدامها.", "This tool is off. Enable it in Settings to use it.", "Cet outil est désactivé. Activez-le dans les paramètres.", "Esta herramienta está desactivada. Actívala en Configuración."],
        ["language"] = ["لغة الواجهة", "Interface language", "Langue de l’interface", "Idioma de la interfaz"],
        ["dark"] = ["المظهر الداكن", "Dark appearance", "Apparence sombre", "Apariencia oscura"],
        ["startup"] = ["التشغيل عند تسجيل الدخول إلى ويندوز", "Launch at Windows sign-in", "Lancer à l’ouverture de session Windows", "Iniciar al entrar en Windows"],
        ["startupScan"] = ["فحص الملف المختار عند بدء التطبيق", "Inspect selected file on app startup", "Analyser le fichier choisi au démarrage", "Analizar el archivo elegido al iniciar"],
        ["explorer"] = ["إضافة التحويل إلى قائمة مستكشف الملفات", "Add conversion to Explorer context menu", "Ajouter la conversion au menu de l’Explorateur", "Añadir conversión al menú del Explorador"],
        ["explorerNote"] = ["حدّد الصور في مستكشف الملفات ثم اضغط Ctrl + كليك يمين بينما بصيرة مفتوح. ويتوفر أمر عادي في «إظهار المزيد من الخيارات».", "Select images in Explorer, then Ctrl + right-click while Baseera is open. A regular command also appears under ‘Show more options’.", "Sélectionnez les images dans l’Explorateur, puis Ctrl + clic droit avec Baseera ouvert. Une commande figure aussi dans « Afficher plus d’options ».", "Selecciona imágenes en el Explorador y pulsa Ctrl + clic derecho con Baseera abierto. También hay un comando en « Mostrar más opciones »."],
        ["save"] = ["حفظ الإعدادات", "Save settings", "Enregistrer", "Guardar ajustes"],
