        ["cancel"] = ["إلغاء", "Cancel", "Annuler", "Cancelar"],
        ["export"] = ["حفظ التقرير", "Save report", "Enregistrer le rapport", "Guardar informe"],
        ["scanNote"] = ["تحليل ثابت دون تشغيل الملفات. لا يكشف كل التهديدات ولا يمنح شهادة أمان. RAR و7z والحزم المشفرة والتحليل السلوكي غير مدعومة بعد.", "Static analysis without execution. Not a malware verdict or safety guarantee. RAR, 7z, encrypted archives and behavioral analysis are not supported yet.", "Analyse statique sans exécution : aucune garantie de sécurité. RAR, 7z, archives chiffrées et analyse comportementale non pris en charge.", "Análisis estático sin ejecutar archivos: no garantiza seguridad. RAR, 7z, archivos cifrados y análisis de comportamiento aún no compatibles."],
        ["review"] = ["توجد مؤشرات تحتاج مراجعة", "Indicators need review", "Indices à examiner", "Indicios para revisar"],
        ["incomplete"] = ["الفحص غير مكتمل — راجع الأجزاء المتخطاة", "Incomplete — review skipped content", "Incomplet — consultez le contenu ignoré", "Incompleto — revisa el contenido omitido"],
        ["no-indicators"] = ["لم تُكتشف مؤشرات بالقواعد الحالية — ليس ضمانًا للأمان", "No indicators under current rules — not proof of safety", "Aucun indice selon les règles actuelles — sécurité non garantie", "Sin indicios con las reglas actuales — no garantiza seguridad"],
