        ["apiKey"] = ["مفتاح Gemini — يُحمى بحساب ويندوز المحلي", "Gemini key — protected with your Windows account", "Clé Gemini — protégée par votre compte Windows", "Clave Gemini — protegida por tu cuenta de Windows"],
        ["keySaved"] = ["يوجد مفتاح محفوظ؛ اترك الحقل فارغًا للاحتفاظ به", "A key is saved; leave blank to keep it", "Une clé est enregistrée ; laissez vide pour la garder", "Hay una clave guardada; déjalo vacío para conservarla"],
        ["forgetKey"] = ["حذف المفتاح المحفوظ", "Forget saved key", "Supprimer la clé", "Eliminar clave guardada"],
        ["refresh"] = ["تحديث القائمة", "Refresh list", "Actualiser la liste", "Actualizar lista"],
        ["target"] = ["لغة الترجمة", "Target language", "Langue cible", "Idioma de destino"],
        ["translateNow"] = ["التقاط النافذة وترجمتها", "Capture and translate window", "Capturer et traduire la fenêtre", "Capturar y traducir ventana"],
        ["hideOverlay"] = ["إغلاق الترجمة", "Close translation", "Fermer la traduction", "Cerrar traducción"],
        ["translateNote"] = ["اختر نافذة مفتوحة؛ ستُستعاد النافذة المصغّرة قبل الالتقاط. الترجمة طبقة فوق الشاشة تُغلق بزر Esc. تُرسل الصورة إلى الخدمة المختارة عند الضغط فقط، وقد لا تسمح النوافذ المحمية بالتقاطها.", "Choose an open window; minimized windows are restored before capture. Translation is an overlay closed with Esc. The image goes to your chosen service only when you click; protected windows may block capture.", "Choisissez une fenêtre ouverte ; les fenêtres réduites sont restaurées avant la capture. Échap ferme la traduction. L’image est envoyée au service choisi uniquement sur demande ; certaines fenêtres protégées bloquent la capture.", "Elige una ventana abierta; las minimizadas se restauran antes de capturarlas. Esc cierra la traducción. La imagen se envía al servicio elegido solo al pulsar; algunas ventanas protegidas bloquean la captura."],
        ["needsKey"] = ["اضبط اتصال خدمة الذكاء الاصطناعي واختر نموذج صور في الإعدادات أولًا.", "Set up an AI service connection and choose an image-capable model in Settings first.", "Configurez une connexion IA et choisissez un modèle avec vision dans les paramètres.", "Configura una conexión de IA y elige un modelo con visión en Configuración."],
        ["aiDirectServices"] = ["20 خدمة مباشرة. استخدم مفتاح الخدمة، أو سجّل الدخول بحسابك عندما يتوفر ربط رسمي مدعوم.", "20 direct services. Use a service key, or sign in to your account where an official integration is supported.", "20 services directs. Utilisez une clé ou connectez votre compte lorsqu’une intégration officielle est prise en charge.", "20 servicios directos. Usa una clave o inicia sesión cuando exista una integración oficial compatible."],
        ["aiNoVisionModels"] = ["لم تُرجع الخدمة نماذج صور يمكن التحقق منها. تحقق من صلاحيات المفتاح ومنطقة حسابك، أو اختر خدمة أخرى.", "The service returned no verifiable image-capable models. Check key permissions and account region, or choose another service.", "Le service n’a renvoyé aucun modèle avec vision vérifiable. Vérifiez les droits de la clé et la région du compte, ou choisissez un autre service.", "El servicio no devolvió modelos con visión verificables. Comprueba los permisos de la clave y la región de la cuenta, o elige otro servicio."],
        ["aiService"] = ["مزود الخدمة", "Provider", "Fournisseur", "Proveedor"],
        ["aiKey"] = ["مفتاح API للخدمة المختارة", "API key for selected service", "Clé API du service choisi", "Clave API del servicio elegido"],
        ["aiLoadModels"] = ["تحميل النماذج المتاحة", "Load available models", "Charger les modèles disponibles", "Cargar modelos disponibles"],
        ["aiModelsNote"] = ["تظهر النماذج الداعمة للصور بحسب بيانات الخدمة أو عائلات النماذج الموثقة. قد تحتاج رصيدًا أو تفعيلًا. عند غياب السعر يظهر «حسب الحساب». لا يلزم كتابة اسم النموذج.", "Only image-capable models appear, using service metadata or documented model families. Access may require credit or activation. Missing pricing is shown as account-dependent. No model ID entry is needed.", "Seuls les modèles avec vision sont affichés selon les données du service ou les familles documentées. Un crédit ou une activation peut être nécessaire. Les tarifs absents dépendent du compte. Aucun identifiant à saisir.", "Solo aparecen modelos con visión según los datos del servicio o las familias documentadas. Pueden requerir saldo o activación. Sin precios publicados, se indica que dependen de la cuenta. No hay que escribir identificadores."],
        ["aiMaker"] = ["جهة النموذج", "Model maker", "Éditeur du modèle", "Creador del modelo"],
        ["aiAllMakers"] = ["كل الجهات", "All makers", "Tous les éditeurs", "Todos los creadores"],
        ["aiFree"] = ["مجاني", "Free", "Gratuit", "Gratis"],
        ["aiPaid"] = ["مدفوع", "Paid", "Payant", "De pago"],
        ["aiTierVaries"] = ["حسب حسابك", "Depends on account", "Selon votre compte", "Según tu cuenta"],
        ["aiNeedKey"] = ["أدخل مفتاح الخدمة أولًا.", "Enter the service key first.", "Saisissez d’abord la clé du service.", "Introduce primero la clave del servicio."],
        ["aiCatalogFailed"] = ["تعذّر تحميل النماذج. تحقق من المفتاح والاتصال.", "Could not load models. Check your key and connection.", "Impossible de charger les modèles. Vérifiez la clé et la connexion.", "No se pudieron cargar los modelos. Comprueba la clave y la conexión."],
        ["aiChooseModel"] = ["أضف المفتاح واختر نموذجًا من القائمة أولًا.", "Add a key and choose a model from the list first.", "Ajoutez une clé et choisissez un modèle dans la liste.", "Añade una clave y elige un modelo de la lista."],
        ["aiRefreshAfterKey"] = ["حمّل النماذج مجددًا بعد تغيير المفتاح.", "Reload models after changing the key.", "Rechargez les modèles après avoir changé de clé.", "Vuelve a cargar los modelos después de cambiar la clave."],
        ["aiLoadingModels"] = ["جارٍ تحميل النماذج…", "Loading models…", "Chargement des modèles…", "Cargando modelos…"],
        ["aiModelsFound"] = ["نماذج داعمة للصور: {0}", "Image-capable models: {0}", "Modèles compatibles avec les images : {0}", "Modelos compatibles con imágenes: {0}"],
        ["selectWindow"] = ["اختر النافذة المراد ترجمتها", "Choose a window to translate", "Choisissez une fenêtre à traduire", "Elige una ventana para traducir"],
        ["auto"] = ["تحديث تلقائي", "Auto update", "Mise à jour automatique", "Actualización automática"],
        ["updateNow"] = ["تحديث المحدد الآن", "Update selected now", "Mettre à jour la sélection", "Actualizar selección"],
        ["updateNote"] = ["يحدّث فقط التطبيقات المحددة عبر WinGet عند تشغيل الأداة، ثم كل 6 ساعات ما دامت مفتوحة. تسجيل الدخول أو الصلاحيات قد يحتاجان تدخلك.", "Only selected WinGet apps update at startup and every 6 hours while open. Authentication or elevation may need your action.", "Seules les applications WinGet choisies sont mises à jour au démarrage puis toutes les 6 heures. Une connexion ou élévation peut être nécessaire.", "Solo las aplicaciones WinGet elegidas se actualizan al iniciar y cada 6 horas mientras está abierta. Puede requerir autenticación o permisos."],
        ["releasePage"] = ["صفحة تنزيل الإصدارات — مصدر يدوي", "Release downloads page — manual source", "Page des versions — source manuelle", "Página de versiones — fuente manual"],
        ["checkRelease"] = ["عرض أحدث إصدار", "Show latest release", "Afficher la dernière version", "Ver última versión"],
        ["releaseNote"] = ["يدعم حاليًا صفحات GitHub Releases. الروابط اليدوية تعرض ملفات الإصدار للمراجعة ولا تشغّل مثبتًا تلقائيًا. المواقع الأخرى تحتاج موصلًا خاصًا.", "Currently supports GitHub Releases pages. Manual sources show release assets for review and never run installers automatically. Other sites need an adapter.", "Prend en charge GitHub Releases. Les fichiers sont proposés à la vérification, sans installation automatique. Les autres sites nécessitent un adaptateur.", "Compatible con GitHub Releases. Muestra archivos para revisión sin instalar automáticamente. Otros sitios necesitan un adaptador."],
        ["unsupportedSource"] = ["هذه الصفحة غير مدعومة بعد. استخدم رابط GitHub Releases.", "This page is not supported yet. Use a GitHub Releases URL.", "Page non prise en charge. Utilisez GitHub Releases.", "Página aún no compatible. Usa una URL de GitHub Releases."],
        ["openDownload"] = ["فتح رابط التنزيل", "Open download link", "Ouvrir le lien", "Abrir enlace de descarga"],
        ["chooseImages"] = ["اختيار الصور", "Choose images", "Choisir des images", "Elegir imágenes"],
        ["output"] = ["صيغة الإخراج", "Output format", "Format de sortie", "Formato de salida"],
        ["convertNow"] = ["تحويل وحفظ", "Convert and save", "Convertir et enregistrer", "Convertir y guardar"],
        ["convertNote"] = ["يحتفظ بالأصل. PNG وJPEG وBMP وTIFF مدعومة؛ PDF يجمع الصور حسب الترتيب الظاهر. TIFF المتعدد الصفحات والصور المتحركة: الإطار الأول فقط.", "Originals are preserved. PNG, JPEG, BMP and TIFF supported; PDF combines images in the displayed order. Multi-page TIFF and animations: first frame only.", "Originaux conservés. PNG, JPEG, BMP et TIFF ; PDF dans l’ordre affiché. TIFF multipage et animations : première image uniquement.", "Conserva originales. PNG, JPEG, BMP y TIFF; PDF en el orden mostrado. TIFF multipágina y animaciones: solo primer fotograma."],
