        ["quality"] = ["جودة JPEG", "JPEG quality", "Qualité JPEG", "Calidad JPEG"],
        ["noText"] = ["لم يُرجع النموذج نصوصًا قابلة للعرض.", "The model returned no displayable text.", "Le modèle n’a renvoyé aucun texte affichable.", "El modelo no devolvió texto visible."],
        ["scanProgress"] = ["جارٍ فحص المحتوى", "Inspecting content", "Analyse du contenu", "Analizando contenido"],
        ["inspectedFiles"] = ["الملفات التي تم فحص محتواها", "Inspected file contents", "Contenu des fichiers analysés", "Contenido de archivos analizados"],
        ["scanLimits"] = ["يقرأ حتى 1 GiB لكل ملف و4 GiB إجمالاً. يفحص محتويات ZIP ضمن حدود العمق والضغط؛ حد فهرسة ZIP المتداخل 32 MiB. يوضح أي محتوى تعذّر فحصه.", "Reads up to 1 GiB per file and 4 GiB total. ZIP contents have depth and compression limits; nested ZIP indexing is limited to 32 MiB. Skipped content is reported.", "Lecture jusqu’à 1 GiB par fichier et 4 GiB au total. Profondeur et compression ZIP limitées ; indexation des ZIP imbriqués limitée à 32 MiB. Le contenu ignoré est signalé.", "Lee hasta 1 GiB por archivo y 4 GiB en total. ZIP con límites de profundidad y compresión; índice de ZIP anidados de hasta 32 MiB. Se indica el contenido omitido."],
        ["scanTotalLimit"] = ["بلغ الفحص حد إجمالي البيانات. التقرير غير مكتمل، ولا يؤكد سلامة المحتوى المتبقي.", "The total data limit was reached. The report is incomplete; remaining content has not been cleared.", "Limite totale atteinte. Rapport incomplet ; le contenu restant n’a pas été validé.", "Se alcanzó el límite total. Informe incompleto; no se ha validado el contenido restante."],
        ["scanFileLimit"] = ["يتجاوز حجم الملف حد الفحص البالغ 1 GiB. لم يُفحص محتواه.", "This file exceeds the 1 GiB inspection limit. Its contents were not inspected.", "Ce fichier dépasse la limite de 1 GiB. Son contenu n’a pas été analysé.", "Este archivo supera el límite de 1 GiB. Su contenido no fue analizado."],
        ["scanUnsigned"] = ["لا يوجد جدول توقيع مضمّن. هذا وحده لا يعني أن الملف ضار.", "No embedded certificate table. This alone is not evidence of malware.", "Aucune table de certificat intégrée. Ce seul fait ne prouve pas la présence d’un logiciel malveillant.", "No hay certificado integrado. Esto por sí solo no indica malware."],
