        ["scan-download-and-execute"] = ["نمط تنزيل وتشغيل", "Download and execution pattern", "Téléchargement et exécution", "Patrón de descarga y ejecución"],
        ["scan-browser-data-reference"] = ["إشارة إلى بيانات المتصفح", "Browser data reference", "Référence aux données du navigateur", "Referencia a datos del navegador"],
        ["scan-startup-persistence"] = ["إشارة إلى التشغيل التلقائي", "Startup persistence reference", "Référence au démarrage automatique", "Referencia a persistencia al inicio"],
        ["scan-defender-setting-change"] = ["إشارة إلى تغيير إعدادات الحماية", "Protection settings reference", "Référence aux paramètres de protection", "Referencia a ajustes de protección"],
        ["scan-process-injection-api"] = ["واجهة تعديل عمليات أخرى", "Process injection API reference", "Référence à une API d’injection", "Referencia a API de inyección"],
        ["scan-credential-api"] = ["واجهة الوصول لبيانات الاعتماد", "Credential API reference", "Référence à une API d’identifiants", "Referencia a API de credenciales"],
        ["scan-writable-executable-section"] = ["قسم قابل للكتابة والتنفيذ", "Writable executable section", "Section exécutable et modifiable", "Sección ejecutable y modificable"],
        ["scan-archive-path"] = ["مسار أرشيف يحتاج مراجعة", "Archive path needs review", "Chemin d’archive à vérifier", "Ruta de archivo que requiere revisión"],
        ["scan-archive-symlink"] = ["رابط رمزي داخل الأرشيف", "Symbolic link in archive", "Lien symbolique dans l’archive", "Enlace simbólico en el archivo"],
        ["smartDiagnostics"] = ["تشخيصات اختيارية — قراءة فقط", "Optional read-only diagnostics", "Diagnostics facultatifs en lecture seule", "Diagnósticos opcionales de solo lectura"],
        ["smartDiagnosticsHelp"] = ["اختر المصادر والفترة التي تسمح بقراءتها ثم اجمعها محليًا، حتى 15 حدثًا حرجًا أو خطأ لكل سجل. لا نقرأ سجل Security أو مخازن كلمات المرور أو ملفاتك. التنقيح الآلي غير مضمون: راجع النص واحذف أي تفاصيل خاصة قبل الموافقة على إرساله.", "Select sources and a time range, then collect locally: at most 15 critical/error events per log. No Security log, password stores or personal files are read. Automatic redaction is imperfect: review and remove private details before approving transmission.", "Choisissez les sources et la période à lire localement : au plus 15 erreurs/événements critiques par journal. Aucun journal Security, coffre de mots de passe ou fichier personnel. Le masquage est imparfait : vérifiez le texte avant tout envoi.", "Elige fuentes y periodo para leer localmente: hasta 15 errores/eventos críticos por registro. Sin registro Security, almacenes de contraseñas ni archivos personales. La ocultación es imperfecta: revisa el texto antes de autorizar su envío."],
        ["smartCaseChanged"] = ["تغيّر الوصف أو الصورة بعد التحليل. حلّل المدخلات الجديدة لتفعيل إصلاحاتها. التقرير المحفوظ يخص التحليل السابق.", "The description or image changed after analysis. Analyze the new input to enable its repairs. Export still refers to the previous analysis.", "La description ou l’image a changé. Analysez les nouvelles données pour activer leurs réparations. L’export concerne l’analyse précédente.", "La descripción o imagen cambió. Analiza los nuevos datos para habilitar sus reparaciones. La exportación corresponde al análisis anterior."],
        ["smartSystemInfo"] = ["ملخص النظام والمساحة الحرة", "System summary and free space", "Résumé système et espace libre", "Resumen del sistema y espacio libre"],
        ["smartApplicationEvents"] = ["أخطاء سجل Application", "Application log errors", "Erreurs du journal Application", "Errores del registro Application"],
        ["smartSystemEvents"] = ["أخطاء سجل System", "System log errors", "Erreurs du journal System", "Errores del registro System"],
        ["smartCollect"] = ["جمع المصادر المحددة محليًا", "Collect selected sources locally", "Lire les sources sélectionnées localement", "Recopilar fuentes seleccionadas localmente"],
        ["smartShareConsent"] = ["راجعت النص الظاهر وأوافق على إرساله إلى خدمة الذكاء الاصطناعي المحددة مع التحليل القادم فقط.", "I reviewed the displayed text and approve sending it to the selected AI service with the next analysis only.", "J’ai vérifié le texte affiché et autorise son envoi au service IA sélectionné pour la prochaine analyse uniquement.", "Revisé el texto mostrado y autorizo enviarlo al servicio de IA seleccionado solo con el próximo análisis."],
        ["smartClear"] = ["مسح بيانات التشخيص من النافذة", "Clear diagnostic text", "Effacer les diagnostics", "Borrar diagnósticos"],
        ["smartChooseSource"] = ["اختر مصدر تشخيص واحدًا على الأقل.", "Select at least one diagnostic source.", "Choisissez au moins une source.", "Selecciona al menos una fuente."],
        ["smartCollecting"] = ["جارٍ جمع التشخيصات محليًا…", "Collecting diagnostics locally…", "Lecture locale des diagnostics…", "Recopilando diagnósticos localmente…"],
        ["smartReviewData"] = ["راجع بيانات التشخيص قبل الموافقة على مشاركتها. لم تُرسل بعد.", "Review the diagnostic text before approving sharing. It has not been sent.", "Vérifiez les diagnostics avant d’autoriser leur partage. Aucun envoi effectué.", "Revisa los diagnósticos antes de autorizar su envío. Aún no se han enviado."],
        ["smartCollectFailed"] = ["تعذّر جمع التشخيصات.", "Could not collect diagnostics.", "Impossible de lire les diagnostics.", "No se pudieron recopilar los diagnósticos."],
        ["smartReviewRecipient"] = ["تغيّرت خدمة الذكاء الاصطناعي. راجع النص وأعد الموافقة قبل مشاركته.", "The AI connection changed. Review the text and approve sharing again.", "Le service IA a changé. Vérifiez le texte et autorisez à nouveau son partage.", "Cambió la conexión de IA. Revisa el texto y autoriza de nuevo su envío."],
        ["smartRepairBusy"] = ["توجد عملية إصلاح أخرى قيد التشغيل في بصيرة.", "Another Baseera repair is still running.", "Une autre réparation Baseera est en cours.", "Hay otra reparación de Baseera en curso."],
        ["smartApproveTitle"] = ["مراجعة أمر الإصلاح والموافقة", "Review and approve repair", "Vérifier et autoriser la réparation", "Revisar y autorizar reparación"],
        ["smartExecute"] = ["تشغيل هذا الأمر فقط", "Run this command only", "Exécuter uniquement cette commande", "Ejecutar solo este comando"],
        ["smartAdmin"] = ["سيطلب ويندوز صلاحيات المسؤول لهذا الأمر. يمكنك رفض طلب ويندوز؛ لا تُرفع صلاحيات بصيرة بالكامل.", "Windows will request administrator permission for this command. You may decline; Baseera itself is not elevated.", "Windows demandera les droits administrateur pour cette commande. Vous pouvez refuser ; Baseera reste non élevé.", "Windows solicitará permisos de administrador para este comando. Puedes rechazarlos; Baseera no se eleva."],
        ["smartNetwork"] = ["قد يتصل DISM بخدمة Windows Update لتنزيل ملفات الإصلاح، حسب سياسات ويندوز.", "DISM may contact Windows Update for repair files, depending on Windows policy.", "DISM peut contacter Windows Update pour les fichiers de réparation, selon les stratégies Windows.", "DISM puede contactar con Windows Update para obtener archivos, según las directivas de Windows."],
        ["smartLongRunning"] = ["قد يستغرق الأمر عدة دقائق أو أكثر. يظهر التقدم في نافذة أداة ويندوز. لا يُنهى أمر الصيانة بالقوة عند إغلاق بصيرة.", "This may take several minutes or longer. Progress appears in the Windows tool window. Closing Baseera does not forcibly stop servicing.", "Cela peut prendre plusieurs minutes ou plus. La progression apparaît dans l’outil Windows. Fermer Baseera n’interrompt pas la maintenance de force.", "Puede tardar varios minutos o más. El progreso aparece en la herramienta de Windows. Cerrar Baseera no interrumpe el mantenimiento por la fuerza."],
        ["smartNoGuarantee"] = ["هذه أداة إصلاح محددة، وليست ضمانًا لحل المشكلة. راجع التأثير واحفظ عملك. لا تعيد بصيرة تشغيل الجهاز تلقائيًا ولا توفر تراجعًا تلقائيًا عن تغييرات SFC أو DISM.", "This specific repair does not guarantee a fix. Review its effects and save your work. Baseera never reboots automatically and cannot automatically undo SFC or DISM changes.", "Cette réparation ne garantit pas la résolution. Vérifiez ses effets et sauvegardez votre travail. Aucun redémarrage automatique ni annulation automatique des changements SFC/DISM.", "Esta reparación no garantiza una solución. Revisa sus efectos y guarda tu trabajo. Sin reinicio automático ni reversión automática de cambios de SFC/DISM."],
        ["smartAcknowledge"] = ["فهمت التأثير وأوافق على تشغيل الأمر الظاهر الآن مرة واحدة.", "I understand the effects and approve running the displayed command once now.", "Je comprends les effets et autorise cette commande une seule fois maintenant.", "Entiendo los efectos y autorizo ejecutar una vez el comando mostrado ahora."],
        ["smartReviewRepair"] = ["مراجعة الإصلاح…", "Review repair…", "Vérifier la réparation…", "Revisar reparación…"],
        ["smartRepairDeclined"] = ["أُلغي الطلب. لم يبدأ أمر الإصلاح.", "Canceled. The repair command did not start.", "Annulé. La commande n’a pas démarré.", "Cancelado. El comando no se inició."],
        ["smartRepairRunning"] = ["أداة ويندوز تعمل في نافذتها. انتظر اكتمالها؛ لا يمكن إيقاف الصيانة من زر إلغاء التحليل.", "The Windows tool is running in its own window. Wait for completion; the analysis Cancel button does not interrupt servicing.", "L’outil Windows s’exécute dans sa fenêtre. Attendez sa fin ; Annuler l’analyse n’interrompt pas la maintenance.", "La herramienta de Windows se ejecuta en su ventana. Espera a que termine; cancelar el análisis no interrumpe el mantenimiento."],
        ["smartExitCode"] = ["رمز الخروج", "Exit code", "Code de sortie", "Código de salida"],
        ["smartRepairCompleted"] = ["انتهت الأداة دون رمز خطأ. تحقق من المشكلة مجددًا؛ هذا لا يؤكد أنها حُلّت.", "The tool finished without an error exit code. Check the original problem again; this does not confirm a fix.", "L’outil a terminé sans code d’erreur. Vérifiez le problème initial ; cela ne confirme pas sa résolution.", "La herramienta terminó sin código de error. Comprueba el problema original; esto no confirma una solución."],
        ["smartRestartNeeded"] = ["أفادت الأداة بالحاجة إلى إعادة التشغيل. احفظ عملك وأعد التشغيل بنفسك عندما تكون مستعدًا.", "The tool reported that a restart is needed. Save your work and restart manually when ready.", "L’outil demande un redémarrage. Sauvegardez puis redémarrez manuellement quand vous êtes prêt.", "La herramienta solicita reiniciar. Guarda tu trabajo y reinicia manualmente cuando estés listo."],
        ["smartRepairFailed"] = ["لم تؤكد الأداة نجاح العملية. راجع رسالتها ورمز الخروج قبل المحاولة مجددًا.", "The tool did not report success. Review its message and exit code before trying again.", "L’outil n’a pas signalé de réussite. Vérifiez son message et son code avant de réessayer.", "La herramienta no indicó éxito. Revisa su mensaje y código antes de reintentar."],
        ["smartCloseRunning"] = ["أمر الإصلاح ما زال يعمل في نافذة ويندوز. إغلاق المساعد لا يوقفه، وقد لا تظهر نتيجته هنا. هل تريد إغلاق المساعد؟", "A repair is still running in a Windows window. Closing the assistant will not stop it, and its result may not appear here. Close the assistant?", "Une réparation est en cours dans Windows. Fermer l’assistant ne l’arrête pas et son résultat peut ne pas s’afficher ici. Fermer ?", "Hay una reparación en curso en Windows. Cerrar el asistente no la detiene y quizá no se muestre aquí el resultado. ¿Cerrar?"],
        ["repair-flush-dns"] = ["مسح ذاكرة DNS المؤقتة", "Clear DNS resolver cache", "Vider le cache DNS", "Vaciar caché DNS"],
        ["repairEffect-flush-dns"] = ["يمسح الإدخالات المخزنة مؤقتًا لمحلل DNS في ويندوز. لا يغيّر خوادم DNS أو ملفاتك، وقد يحتاج أول اتصال بعده إلى استعلام جديد.", "Clears cached Windows DNS resolver entries. It does not change DNS servers or personal files; subsequent lookups may take a new network query.", "Vide les entrées DNS en cache. Ne change ni les serveurs DNS ni vos fichiers ; les requêtes suivantes devront être renouvelées.", "Vacía las entradas DNS en caché. No cambia servidores DNS ni archivos personales; las siguientes búsquedas pueden requerir una nueva consulta."],
        ["repair-sfc-repair"] = ["إصلاح ملفات ويندوز المحمية — SFC", "Repair protected Windows files — SFC", "Réparer les fichiers Windows protégés — SFC", "Reparar archivos protegidos de Windows — SFC"],
        ["repairEffect-sfc-repair"] = ["يفحص ملفات النظام المحمية ويحاول استبدال التالف منها بنسخ صحيحة. يعدّل ملفات ويندوز عند اكتشاف تلف؛ ليس إصلاحًا عامًا لكل أخطاء التطبيقات.", "Scans protected system files and attempts to replace corrupted copies. It changes Windows files when corruption is found; it is not a universal app repair.", "Analyse les fichiers système protégés et tente de remplacer les copies endommagées. Modifie les fichiers Windows si nécessaire ; ce n’est pas une réparation universelle.", "Examina archivos protegidos e intenta reemplazar los dañados. Modifica archivos de Windows si hay corrupción; no es una reparación universal de aplicaciones."],
        ["repair-dism-repair"] = ["إصلاح مخزن مكونات ويندوز — DISM", "Repair Windows component store — DISM", "Réparer le magasin de composants — DISM", "Reparar almacén de componentes — DISM"],
        ["repairEffect-dism-repair"] = ["يحاول إصلاح تلف مخزن مكونات نسخة ويندوز الحالية. قد يغيّر مكونات النظام وينزّل ملفات إصلاح، وقد يستغرق وقتًا طويلًا أو يحتاج إعادة تشغيل.", "Attempts to repair component-store corruption in the running Windows installation. It may change system components, download repair files, take significant time or require a restart.", "Tente de réparer le magasin de composants Windows actif. Peut modifier des composants, télécharger des fichiers, prendre du temps ou nécessiter un redémarrage.", "Intenta reparar el almacén de componentes de Windows en ejecución. Puede modificar componentes, descargar archivos, tardar o requerir reiniciar."],
        ["private"] = ["بصيرة لا يرفع ملفات الفحص أو التحويل إلى الإنترنت.", "Inspection and conversion files stay on your device.", "Les fichiers analysés et convertis restent sur votre appareil.", "Los archivos analizados y convertidos permanecen en tu equipo."]
    };
}
